describe('Notification Count Reset After Reading All Messages', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should reset notification count to zero after reading all messages', () => {
    // Verify initial notification count is greater than zero
    cy.get('[data-testid="notification-badge"]').should('be.visible');
    cy.get('[data-testid="notification-badge"]').should('contain', '3');

    // Verify messages are visible
    cy.get('[data-testid="message-item"]').should('have.length', 3);

    // Read first message
    cy.get('[data-testid="message-item:first"]').click();
    cy.get('[data-testid="message-item:first"]').should('have.class', 'read');

    // Verify notification count decreases
    cy.get('[data-testid="notification-badge"]').should('contain', '2');

    // Read second message
    cy.get('[data-testid="message-item:second"]').click();
    cy.get('[data-testid="message-item:second"]').should('have.class', 'read');

    // Verify notification count decreases again
    cy.get('[data-testid="notification-badge"]').should('contain', '1');

    // Read third message
    cy.get('[data-testid="message-item:third"]').click();
    cy.get('[data-testid="message-item:third"]').should('have.class', 'read');

    // Verify notification count resets to zero
    cy.get('[data-testid="notification-badge"]').should('contain', '0');
    cy.get('[data-testid="notification-badge"]').should('not.exist');
  });

  it('should not reset notification count if not all messages are read', () => {
    // Verify initial notification count is greater than zero
    cy.get('[data-testid="notification-badge"]').should('be.visible');
    cy.get('[data-testid="notification-badge"]').should('contain', '5');

    // Read first message
    cy.get('[data-testid="message-item"]').first().click();
    cy.get('[data-testid="message-item"]').first().should('have.class', 'read');

    // Verify notification count decreases
    cy.get('[data-testid="notification-badge"]').should('contain', '4');

    // Verify remaining messages are not marked as read
    cy.get('[data-testid="message-item"]').eq(1).should('not.have.class', 'read');

    // Verify notification count remains greater than zero
    cy.get('[data-testid="notification-badge"]').should('contain', '4');
  });
});
